[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$config = Import-PowerShellDataFile (Join-Path $PSScriptRoot 'deploy-config.psd1')
foreach ($domain in @($config.ProductionDomain, $config.DevDomain)) {
    if ($domain -notmatch '^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$') {
        throw "Invalid deployment hostname: $domain"
    }
}
if ($config.DevDomain -eq $config.ProductionDomain) { throw 'Dev and production domains must differ.' }
if ($config.DevRepository -notmatch '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' -or
    $config.DevRepository -ieq 'Ignyos/solitaire') {
    throw 'DevRepository must be a separate owner/repository.'
}
$docs = Join-Path $PSScriptRoot 'docs'
foreach ($name in @('index.html', 'styles.css', 'main.js', 'dev-site-banner.js',
    'service-worker.js', 'manifest.webmanifest', 'icon.svg', 'CNAME')) {
    $path = Join-Path $docs $name
    if (-not (Test-Path -LiteralPath $path -PathType Leaf) -or (Get-Item $path).Length -eq 0) {
        throw "Required deployment asset missing or empty: $name"
    }
}
if ((Get-Content (Join-Path $docs 'CNAME') -Raw).Trim() -cne $config.ProductionDomain) {
    throw 'Tracked docs/CNAME must contain only the production hostname.'
}
$html = Get-Content (Join-Path $docs 'index.html') -Raw
$versions = @([regex]::Matches($html, '(?:src|href)="[^"]+\?v=(\d{4}-\d{2}-\d{2}-\d{2}-\d{2})"') |
    ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
if ($versions.Count -ne 1) { throw 'HTML must use one consistent UTC timestamp version.' }
foreach ($asset in @('styles.css', 'main.js', 'dev-site-banner.js', 'manifest.webmanifest')) {
    if (-not $html.Contains("${asset}?v=$($versions[0])")) { throw "HTML must reference versioned $asset." }
}
$worker = Get-Content (Join-Path $docs 'service-worker.js') -Raw
if (-not $worker.Contains("const CACHE_NAME = 'solitaire-v$($versions[0])';")) {
    throw 'Service worker cache version must match HTML asset versions.'
}
$banner = Get-Content (Join-Path $docs 'dev-site-banner.js') -Raw
if (-not $banner.Contains("const productionHost = '$($config.ProductionDomain)';")) {
    throw 'Preview banner production host must match deploy-config.psd1.'
}
$manifest = Get-Content (Join-Path $docs 'manifest.webmanifest') -Raw | ConvertFrom-Json
if ($manifest.start_url -ne './' -or $manifest.scope -ne './') { throw 'PWA paths must be deployment-relative.' }
